INSERT INTO SYM0YA
     ( CORP_GR
     , JM_CD
     , JM_NM
     , STOCK_GB
     , JASAN_GB
     , SEQ_NO
     , BALH_NATION
     , CURRENCY
     , IJA_PER
     , BALH_YMD
     , SANGHW_YMD
     , AEKM
     , SANGJ_YMD
     , SANGJ_JUSU
     , GYULJE_JM
     , BLBG_TCKR
     , ISIN_CD
     , IJA_BDC
     , IJA_DCF
     , JASAN_ATTR
     , SJ_GB
     , LSY_YMD
     , UNIT_AEK
     , HANGSA_GA
     , JASAN
     , SEDOL
     , SIGA_AGENT
     , CHANGE_CURRENCY
     , CHANGE_EX_RT
     , CHANGE_JM_CD
     )
VALUES
     ( #{corpGr}
     , #{jmCd}
     , #{jmNm}
     , #{stockGb, jdbcType=VARCHAR}
     , NVL(#{jasanGb}, 'A')
     , NVL(#{seqNo}, 1)
     , #{balhNation, jdbcType=VARCHAR}
     , #{currency, jdbcType=VARCHAR}
     , #{ijaPer, jdbcType=NUMERIC}
     , TO_DATE(REPLACE(#{balhYmd}, '-', ''), 'YYYYMMDD')
     , TO_DATE(REPLACE(#{sanghwYmd}, '-', ''), 'YYYYMMDD')
     , #{aekm, jdbcType=NUMERIC}
     , TO_DATE(REPLACE(#{sangjYmd}, '-', ''), 'YYYYMMDD')
     , #{sangjJusu, jdbcType=NUMERIC}
     , #{gyuljeJm, jdbcType=VARCHAR}
     , #{blbgTckr, jdbcType=VARCHAR}
     , #{isinCd, jdbcType=VARCHAR}
     , #{ijaBdc, jdbcType=VARCHAR}
     , #{ijaDcf, jdbcType=VARCHAR}
     , #{jasanAttr, jdbcType=VARCHAR}
     , #{sjGb, jdbcType=VARCHAR}
     , TO_DATE(REPLACE(#{lsyYmd}, '-', ''), 'YYYYMMDD')
     , #{unitAek, jdbcType=NUMERIC}
     , #{hangsaGa, jdbcType=NUMERIC}
     , #{jasan, jdbcType=VARCHAR}
     , #{sedol, jdbcType=VARCHAR}
     , NVL(#{sigaAgent}, 'B')
     , #{changeCurrency, jdbcType=VARCHAR}
     , #{changeExRt, jdbcType=NUMERIC}
     , #{changeJmCd, jdbcType=VARCHAR}
     )

