   SET JM_NM           = #{jmNm}
     , STOCK_GB        = #{stockGb, jdbcType=VARCHAR}
     , SEQ_NO          = NVL(#{seqNo}, 1)
     , BALH_NATION     = #{balhNation, jdbcType=VARCHAR}
