     , SANGHW_YMD      = TO_DATE(REPLACE(#{sanghwYmd}, '-', ''), 'YYYYMMDD')
     , AEKM            = #{aekm, jdbcType=NUMERIC}
     , SANGJ_YMD       = TO_DATE(REPLACE(#{sangjYmd}, '-', ''), 'YYYYMMDD')
     , SANGJ_JUSU      = #{sangjJusu, jdbcType=NUMERIC}
     , GYULJE_JM       = #{gyuljeJm, jdbcType=VARCHAR}
     , BLBG_TCKR       = #{blbgTckr, jdbcType=VARCHAR}
     , ISIN_CD         = #{isinCd, jdbcType=VARCHAR}
     , IJA_BDC         = #{ijaBdc, jdbcType=VARCHAR}
     , IJA_DCF         = #{ijaDcf, jdbcType=VARCHAR}
     , JASAN_ATTR      = #{jasanAttr, jdbcType=VARCHAR}
     , SJ_GB           = #{sjGb, jdbcType=VARCHAR}
     , LSY_YMD         = TO_DATE(REPLACE(#{lsyYmd}, '-', ''), 'YYYYMMDD')
     , UNIT_AEK        = #{unitAek, jdbcType=NUMERIC}
     , HANGSA_GA       = #{hangsaGa, jdbcType=NUMERIC}
     , JASAN           = #{jasan, jdbcType=VARCHAR}
     , SIGA_AGENT      = NVL(#{sigaAgent}, 'B')
     , CHANGE_CURRENCY = #{changeCurrency, jdbcType=VARCHAR}
     , CHANGE_EX_RT    = #{changeExRt, jdbcType=NUMERIC}
     , CHANGE_JM_CD    = #{changeJmCd, jdbcType=VARCHAR}
 WHERE CORP_GR         = #{corpGr}
   AND JM_CD           = #{jmCd}
   AND JASAN_GB        = NVL(#{jasanGb}, 'A')
   AND SEDOL           = #{sedol}

